// src/pages/Dashboard.jsx
import React, { useEffect, useState } from 'react';
import StatCard from '../components/StatCard';
import MyLineChart from '../components/LineChart';
import MyPieChart from '../components/PieChart';
import RecentActivity from '../components/RecentActivity';
import QuickActions from '../components/QuickActions';
import { fetchDashboardData } from '../services/api';

const Dashboard = () => {
  const [data, setData] = useState(null);

  useEffect(() => {
    fetchDashboardData().then(setData);
  }, []);

  if (!data) return <p>Loading...</p>;

  return (
    <div className="p-6 bg-gray-100 min-h-screen space-y-6">
      <QuickActions />
      
      <div className="grid grid-cols-3 gap-4">
        <StatCard title="Tổng Leads" value={data.totalLeads} />
        <StatCard title="Tổng Landing Page" value={data.totalLandingPages} />
        <StatCard title="Tỷ lệ chuyển đổi" value={`${(data.conversionRate * 100).toFixed(1)}%`} />
      </div>

      <div className="grid grid-cols-2 gap-4">
        <MyLineChart data={data.leadsStats} dataKey="count" nameKey="date" title="Leads theo thời gian" />
        <MyPieChart data={data.leadsStatus} title="Tình trạng Leads" />
      </div>

      <MyLineChart data={data.landingPageStats} dataKey="count" nameKey="week" title="Tăng trưởng Landing Page" />

      <RecentActivity leads={data.recentLeads} landingPages={data.recentLandingPages} />
    </div>
  );
};

export default Dashboard;
